export function PullToRefresh({
  released = {{released}},
  pullDistance = {{pullDistance}},
  duration = {{duration}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, overflow: "hidden", fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <div style={{ display: "flex", alignItems: "center", justifyContent: "center", background: "#24143008", height: released ? 50 : pullDistance }}>
        {released ? (
          <span role="status" aria-live="polite" className="spin" style={{ width: 22, height: 22, border: "3px solid #24143022", borderTopColor: accent, borderRadius: 999 }}>
            <span style={{ position: "absolute", width: 1, height: 1, overflow: "hidden" }}>Refreshing&hellip;</span>
          </span>
        ) : (
          <span>&darr; pull {pullDistance}px</span>
        )}
      </div>
      <div>
        <div style={{ padding: 12, borderTop: "1px solid #24143014", color: "#241430" }}>Item one</div>
        <div style={{ padding: 12, borderTop: "1px solid #24143014", color: "#241430" }}>Item two</div>
      </div>
      <style>{`
        @media (prefers-reduced-motion: no-preference) {
          .spin { animation: rsp-pr-spin ${duration}ms linear infinite; }
          @keyframes rsp-pr-spin { to { transform: rotate(360deg); } }
        }
      `}</style>
    </div>
  );
}
